 runs.append({'path':str(f.relative_to(base)),'sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'engine':m['engine'],'mode':m['mode'],'completed':m.get('completed') is True,'checks':len(m.get('checks',[])),'genuineCorrectAnswers':len(m.get('correctUIAttempts',[])),'cut':m.get('manifestSHA256'),'sourceUnchanged':m.get('sourceUnchangedDuringRun'),'javascriptExceptions':len(m.get('javascriptErrors',[])),'networkErrors':network,'ownedBrowserExited':m.get('ownedBrowserExited'),'ownedServerClosed':m.get('ownedServerClosed'),'ownedProfileRemoved':m.get('ownedProfileRemoved'),'cacheVariants':m.get('cacheVariantSourceMap',{}),'failure':m.get('failure','').splitlines()[-1:]})
